package agentguide

import (
	"fmt"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"strings"

	edits "m31labs.dev/cicada/edit"
	"m31labs.dev/cicada/internal/diagnostics"
)

// FrontDoorCommand rewrites every file Build returns.
const FrontDoorCommand = "CICADA_UPDATE_AGENT_FRONT_DOOR=1 go test ./cmd/cicada -run TestAgentFrontDoorIsCurrent"

// The budgets the generated files must keep, in bytes (about four bytes a
// token).
const (
	ReferenceBudget = 48000  // the core reference: about 12,000 tokens
	LLMsBudget      = 6000   // llms.txt
	LLMsFullBudget  = 240000 // llms-full.txt: about 60,000 tokens
	AgentsMDBudget  = 6000   // the repository's AGENTS.md, generated region included
)

// Command is one line of the command table, which package main holds.
type Command struct {
	Name, Summary string
}

// Inputs are what Build reads: the repository, for the manual pages, and the
// command table. The intent, diagnostic and effect catalogs come from the
// packages that own them.
type Inputs struct {
	Root     string
	Commands []Command
}

// The region of the repository's AGENTS.md that Build writes; the rest of the
// file is written by hand.
const (
	regionBegin = "<!-- agent-front-door:begin -->"
	regionEnd   = "<!-- agent-front-door:end -->"
)

const generatedNote = "<!-- Generated by internal/agentguide from the manual and the binary's catalogs. Do not edit; run\n" + FrontDoorCommand + " -->"

// referencePassages are the manual sections the core reference copies, by
// page and heading. A heading that is renamed or removed fails Build.
var referencePassages = []struct {
	part, page, heading string
}{
	{"Language", "docs/manual/writing-music.md", "## Tracks and patterns"},
	{"Language", "docs/manual/writing-music.md", "## Shape a note"},
	{"Language", "docs/manual/writing-music.md", "## Write drum rows"},
	{"Sound", "docs/audio/mix-chain.md", "## Score master effects"},
	{"Sound", "docs/manual/audition.md", "## JSON schema"},
	{"Formats", "docs/manual/agents.md", "# Agents and JSON output"},
}

// llmsSections are the sections of llms.txt and the pages in each. Every page
// of the manual index (docs/manual/README.md) must be in one, or Build fails.
// Pages outside the index carry their note here. llms-full.txt holds the
// full text of every page outside Optional, except the core reference, whose
// text is that of the other pages and the binary's catalogs.
var llmsSections = []struct {
	name  string
	pages []string
}{
	{"Start here", []string{"docs/manual/agent-quickstart.md", "docs/manual/agent-reference.md", "docs/manual/agents.md"}},
	{"Language", []string{"docs/manual/writing-music.md", "docs/manual/composing-songs.md", "docs/spec/edition-2.md", "docs/spec/features.md"}},
	{"Sound and delivery", []string{"docs/manual/exporting.md", "docs/manual/audition.md", "docs/audio/mix-chain.md", "docs/manual/parameter-ranges.md"}},
	{"Reference", []string{"docs/manual/diagnostics.md", "docs/manual/troubleshooting.md", "docs/cli.md"}},
	{"Optional", []string{"docs/manual/macos.md", "docs/manual/studio.md", "docs/manual/modeled-percussion.md", "docs/manual/sampler.md", "docs/manual/editors.md", "docs/manual/libraries.md", "docs/manual/next-level.md", "docs/manual/modulation.md", "docs/manual/engine-host.md", "docs/manual/engine-metrics.md"}},
}

var outsideIndexNotes = map[string]string{
	"docs/spec/edition-2.md":  "what edition 2 of the language adds and changes",
	"docs/spec/features.md":   "every feature of the language, with its rules",
	"docs/audio/mix-chain.md": "track inserts, sends, master effects, and how loudness targets use the master limiter",
	"docs/cli.md":             "every command and flag of the cicada binary",
}

// Build returns every generated file of the agent front door, by its path
// from the repository root.
func Build(in Inputs) (map[string][]byte, error) {
	read := func(page string) (string, error) {
		data, err := os.ReadFile(filepath.Join(in.Root, filepath.FromSlash(page)))
		return string(data), err
	}
	quickstart, err := read("docs/manual/agent-quickstart.md")
	if err != nil {
		return nil, err
	}
	reference, err := buildReference(in, quickstart, read)
	if err != nil {
		return nil, err
	}
	agents, err := read("AGENTS.md")
	if err != nil {
		return nil, err
	}
	agents, err = replaceRegion(agents, frontDoorRegion(quickstart))
	if err != nil {
		return nil, fmt.Errorf("AGENTS.md: %w", err)
	}
	llms, full, err := buildLLMs(quickstart, reference, read)
	if err != nil {
		return nil, err
	}
	return map[string][]byte{
		"internal/agentguide/quickstart.md": []byte(quickstart),
		"internal/agentguide/reference.md":  []byte(reference),
		"docs/manual/agent-reference.md":    []byte(reference),
		"AGENTS.md":                         []byte(agents),
		"llms.txt":                          []byte(llms),
		"llms-full.txt":                     []byte(full),
		"examples/first-song/AGENTS.md":     []byte(ProjectAgentsFrom(quickstart)),
	}, nil
}

// ProjectAgentsFrom is the AGENTS.md cicada new writes into a project: the
// quick start, under a line that says where it came from.
func ProjectAgentsFrom(quickstart string) string {
	return "<!-- Written by cicada new: the quick start for agents. `cicada agents` prints it for the installed binary, and `cicada agents reference` the core reference. -->\n\n" + quickstart
}

// ProjectAgents is the AGENTS.md this binary's cicada new writes.
func ProjectAgents() string { return ProjectAgentsFrom(QuickStart) }

func buildReference(in Inputs, quickstart string, read func(string) (string, error)) (string, error) {
	var page strings.Builder
	page.WriteString("# Cicada core reference for agents\n\n" + generatedNote + "\n\n")
	page.WriteString("The quick start, the language, sound and JSON formats in brief, then one line\n")
	page.WriteString("for every command, edit intent, diagnostic code and effect route of this\n")
	page.WriteString("binary. `cicada agents reference` prints this page; `cicada agents` prints the\n")
	page.WriteString("quick start alone.\n\n")
	page.WriteString("## Quick start\n\n" + withoutTitle(exampleMarkers.ReplaceAllString(quickstart, "")) + "\n")
	part := ""
	for _, passage := range referencePassages {
		text, err := read(passage.page)
		if err != nil {
			return "", err
		}
		body, err := section(text, passage.heading)
		if err != nil {
			return "", fmt.Errorf("%s: %w", passage.page, err)
		}
		if passage.part != part {
			part = passage.part
			page.WriteString("## " + part + "\n\n")
		}
		if strings.Count(passage.heading, "#") == 1 {
			body = withoutTitle(body) // a whole page's opening: its rules, not its title
		} else {
			body = demote(body)
		}
		page.WriteString(rebaseLinks(body, path.Dir(passage.page), "docs/manual") + "\n")
	}
	agentsPage, err := read("docs/manual/agents.md")
	if err != nil {
		return "", err
	}
	for _, list := range []struct{ title, marker string }{{"apply", "apply-error-codes"}, {"render", "render-error-codes"}} {
		codes, err := between(agentsPage, "<!-- "+list.marker+" -->", "<!-- /"+list.marker+" -->")
		if err != nil {
			return "", fmt.Errorf("docs/manual/agents.md: %w", err)
		}
		fmt.Fprintf(&page, "### Error codes of %s --json\n\n%s\n", list.title, strings.TrimSpace(codes)+"\n")
	}
	page.WriteString("## Commands\n\n")
	for _, command := range in.Commands {
		fmt.Fprintf(&page, "- `cicada %s`: %s\n", command.Name, command.Summary)
	}
	page.WriteString("\n## Edit intents\n\n`cicada intents --json <kind>` gives a kind's fields and examples.\n\n")
	for _, info := range edits.Catalog() {
		fmt.Fprintf(&page, "- `%s`: %s\n", info.Kind, oneLine(info.Meaning))
	}
	page.WriteString("\n## Diagnostic codes\n\n`cicada diagnostics --json <code>` gives a code's fix.\n\n")
	for _, code := range diagnostics.Catalog() {
		fmt.Fprintf(&page, "- `%s` (%s): %s\n", code.Code, strings.Join(code.Severities, ", "), oneLine(code.Meaning))
	}
	page.WriteString("\n## Effect routes\n\nWhere `addeffect` may put each kind. A send return takes no `inserton`;\nraise `param:<track>.send.<name>` instead.\n\n")
	page.WriteString("| Kind | Inserted on | Send return | Only in an insert chain |\n| --- | --- | --- | --- |\n")
	for _, route := range edits.EffectRoutes() {
		on := strings.Join(route.InsertOn, ", ")
		if on == "" {
			on = "none"
		}
		fmt.Fprintf(&page, "| `%s` | %s | %s | %s |\n", route.Kind, on, yes(route.Return), yes(route.InsertsOnly))
	}
	return page.String(), nil
}

func frontDoorRegion(quickstart string) string {
	loop, err := section(quickstart, "## The loop")
	if err != nil {
		loop = ""
	}
	loop = strings.TrimSpace(strings.TrimPrefix(loop, "## The loop"))
	if before, _, found := strings.Cut(loop, "\n\n"); found && strings.HasPrefix(loop, "1.") {
		loop = before
	}
	loop = strings.ReplaceAll(loop, "(next section)", "(the quick start's next section)")
	var region strings.Builder
	region.WriteString(regionBegin + "\n")
	region.WriteString("## Using Cicada to make music\n\n")
	region.WriteString("<!-- Generated from docs/manual/agent-quickstart.md; run " + FrontDoorCommand + " -->\n\n")
	region.WriteString("An agent that makes music with an installed `cicada` binary starts with\n")
	region.WriteString("`cicada agents`, which prints the quick start\n")
	region.WriteString("([docs/manual/agent-quickstart.md](docs/manual/agent-quickstart.md)). Its loop:\n\n")
	region.WriteString(loop + "\n\n")
	region.WriteString("`cicada agents reference` prints the core reference\n")
	region.WriteString("([docs/manual/agent-reference.md](docs/manual/agent-reference.md)), and\n")
	region.WriteString("[llms.txt](llms.txt) lists the manual for agents.\n")
	region.WriteString(regionEnd)
	return region.String()
}

func replaceRegion(file, region string) (string, error) {
	start := strings.Index(file, regionBegin)
	end := strings.Index(file, regionEnd)
	if start < 0 || end < start {
		return "", fmt.Errorf("no %s ... %s region", regionBegin, regionEnd)
	}
	return file[:start] + region + file[end+len(regionEnd):], nil
}

func buildLLMs(quickstart, reference string, read func(string) (string, error)) (string, string, error) {
	index, err := read("docs/manual/README.md")
	if err != nil {
		return "", "", err
	}
	notes := map[string]string{}
	entry := regexp.MustCompile(`^- \[[^\]]+\]\(([^)]+)\) — (.*)$`)
	current := ""
	for _, line := range strings.Split(index, "\n") {
		if match := entry.FindStringSubmatch(line); match != nil {
			current = "docs/manual/" + match[1]
			notes[current] = match[2]
		} else if current != "" && strings.HasPrefix(line, "  ") {
			notes[current] += " " + strings.TrimSpace(line)
		} else {
			current = ""
		}
	}
	placed := map[string]bool{}
	var llms, full strings.Builder
	llms.WriteString("# Cicada\n\n")
	llms.WriteString("> Cicada is a music workstation in which a song is a readable text score. The\n")
	llms.WriteString("> same score renders to the same audio on every machine and in the browser.\n\n")
	llms.WriteString("An agent starts with `cicada agents`, which prints the quick start: write a\n")
	llms.WriteString("score, `cicada check --json`, `cicada render --json`, `cicada audition --json`,\n")
	llms.WriteString("then edit it with `cicada apply`. `cicada agents reference` prints the core reference.\n")
	full.WriteString("# Cicada: the manual for agents\n\n" + generatedNote + "\n\n")
	full.WriteString("The quick start, then the full text of the manual pages that llms.txt lists\n")
	full.WriteString("outside Optional. Links are relative to the repository root.\n")
	for _, section := range llmsSections {
		fmt.Fprintf(&llms, "\n## %s\n\n", section.name)
		for _, page := range section.pages {
			text := reference
			if page != "docs/manual/agent-reference.md" {
				if text, err = read(page); err != nil {
					return "", "", err
				}
			}
			note := notes[page]
			if note == "" {
				note = outsideIndexNotes[page]
			}
			if note == "" {
				return "", "", fmt.Errorf("llms.txt: %s has no note in docs/manual/README.md or outsideIndexNotes", page)
			}
			placed[page] = true
			fmt.Fprintf(&llms, "- [%s](%s): %s\n", title(text), page, strings.TrimSuffix(note, "."))
			if section.name == "Optional" || page == "docs/manual/agent-reference.md" {
				continue
			}
			fmt.Fprintf(&full, "\n# %s\n\n%s", page, rebaseLinks(text, path.Dir(page), "."))
		}
	}
	for page := range notes {
		if !placed[page] {
			return "", "", fmt.Errorf("llms.txt: %s is in the manual index but in no section; add it to llmsSections", page)
		}
	}
	return llms.String(), full.String(), nil
}

// section returns the text of a page from the heading line to the next
// heading of the same or a higher level, outside fenced blocks. For a page's
// title (level 1) it is the page's opening, up to its first section.
func section(text, heading string) (string, error) {
	level := max(strings.Count(strings.Fields(heading)[0], "#"), 2)
	lines := strings.Split(text, "\n")
	start := -1
	fenced := false
	for i, line := range lines {
		if strings.HasPrefix(strings.TrimSpace(line), "```") {
			fenced = !fenced
		}
		if fenced {
			continue
		}
		if start < 0 {
			if line == heading {
				start = i
			}
			continue
		}
		if hashes := len(line) - len(strings.TrimLeft(line, "#")); hashes > 0 && hashes <= level && strings.HasPrefix(line[hashes:], " ") {
			return strings.TrimRight(strings.Join(lines[start:i], "\n"), "\n") + "\n", nil
		}
	}
	if start < 0 {
		return "", fmt.Errorf("no heading %q", heading)
	}
	return strings.TrimRight(strings.Join(lines[start:], "\n"), "\n") + "\n", nil
}

// demote adds one level to every heading outside fenced blocks.
func demote(text string) string {
	lines := strings.Split(text, "\n")
	fenced := false
	for i, line := range lines {
		if strings.HasPrefix(strings.TrimSpace(line), "```") {
			fenced = !fenced
		}
		if !fenced && strings.HasPrefix(line, "#") {
			lines[i] = "#" + line
		}
	}
	return strings.Join(lines, "\n")
}

// between returns the text between two marker lines.
func between(text, begin, end string) (string, error) {
	_, after, found := strings.Cut(text, begin)
	inner, _, closed := strings.Cut(after, end)
	if !found || !closed {
		return "", fmt.Errorf("no %s ... %s", begin, end)
	}
	return inner, nil
}

// withoutTitle drops a page's first heading line and the blank lines after it.
func withoutTitle(text string) string {
	if strings.HasPrefix(text, "#") {
		_, text, _ = strings.Cut(text, "\n")
	}
	return demote(strings.TrimLeft(text, "\n"))
}

// title is a page's first level-1 heading.
func title(text string) string {
	for _, line := range strings.Split(text, "\n") {
		if strings.HasPrefix(line, "# ") {
			return strings.TrimSpace(line[2:])
		}
	}
	return ""
}

var markdownLink = regexp.MustCompile(`\]\(([^)\s]+)\)`)

// exampleMarkers are the lines of the quick start that the documentation
// harness reads (agent-example markers and the blank line after each); the
// reference leaves them out.
var exampleMarkers = regexp.MustCompile(`(?m)^<!-- agent-example[^>]*-->\n\n?`)

// rebaseLinks rewrites relative links of text, written for a page in from,
// so they resolve from the folder to (both relative to the repository root).
func rebaseLinks(text, from, to string) string {
	return markdownLink.ReplaceAllStringFunc(text, func(link string) string {
		target := link[2 : len(link)-1]
		if strings.Contains(target, "://") || strings.HasPrefix(target, "#") || strings.HasPrefix(target, "/") || strings.HasPrefix(target, "mailto:") {
			return link
		}
		file, anchor, _ := strings.Cut(target, "#")
		rebased := relative(to, path.Join(from, file))
		if anchor != "" {
			rebased += "#" + anchor
		}
		return "](" + rebased + ")"
	})
}

// relative returns the slash path of target relative to the folder dir.
func relative(dir, target string) string {
	dirParts := strings.Split(path.Clean(dir), "/")
	targetParts := strings.Split(path.Clean(target), "/")
	if dirParts[0] == "." {
		dirParts = nil
	}
	common := 0
	for common < len(dirParts) && common < len(targetParts)-1 && dirParts[common] == targetParts[common] {
		common++
	}
	var parts []string
	for range dirParts[common:] {
		parts = append(parts, "..")
	}
	return strings.Join(append(parts, targetParts[common:]...), "/")
}

func oneLine(text string) string { return strings.Join(strings.Fields(text), " ") }

func yes(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}
